from h import *

add(6057764,
es=T("Potaje de verduras de invierno con pasta","Esta sopa para el clima frío es la forma perfecta y saludable para el corazón de mantenerse caliente. La fibra de las verduras ayuda a equilibrar la pasta, para crear un caldo sustancioso que es el acompañamiento perfecto, un almuerzo o incluso un plato principal reconfortante para la cena.","8","1 taza",
["2 cucharadas de cebollín fresco (picado muy fino)","2/3 taza de macarrones de codo","1/2 taza de colinabo (rutabaga) (pelado y en cubos)","1 taza de repollo (rallado)","5 tazas de caldo de pollo bajo en sodio","2 dientes de ajo (picados)","1/4 cucharadita de pimienta negra","1/2 cucharadita de sal","1 bulbo de hinojo entero (en cubos)","3 zanahorias medianas (peladas y en cubos)","1 cebolla mediana (en cubos)","1 cucharada de aceite de oliva"],
["En una cacerola grande, caliente el aceite de oliva a fuego medio-alto. Agregue las cebollas y saltee durante 4 minutos. Agregue las zanahorias y el hinojo y sazone con la sal y la pimienta negra. Saltee durante 3 minutos. Agregue el ajo y saltee durante 1 minuto.","Agregue el caldo, el repollo y el colinabo (rutabaga) a la cacerola. Deje que hierva. Reduzca el fuego a bajo, tape y cocine a fuego lento de 45 minutos a 1 hora. Agregue la pasta, suba el fuego a medio y cocine durante 7 minutos, o hasta que la pasta esté tierna. Sirva la sopa en tazones y decore cada tazón con el cebollín."]),
ar=T("حساء الخضار الشتوي مع المعكرونة","هذا الحساء المناسب للطقس البارد هو الطريقة المثالية والصحية للقلب للحصول على الدفء. تساعد ألياف الخضار على موازنة المعكرونة، لتكوين مرق غني هو الطبق الجانبي المثالي، أو وجبة غداء، أو حتى طبق رئيسي مُشبع للعشاء.","8","1 كوب",
["2 ملعقة كبيرة ثوم معمّر (شيف) طازج (مفروم ناعمًا)","⅔ كوب معكرونة مرفقية","½ كوب لفت سويدي (روتاباغا) (مقشر ومقطع مكعبات)","1 كوب ملفوف (مبشور)","5 كوب مرق دجاج قليل الصوديوم","2 فص ثوم (مفروم)","¼ ملعقة صغيرة فلفل أسود","½ ملعقة صغيرة ملح","1 حبة بصلة شمر كاملة (مقطعة مكعبات)","3 حبات جزر متوسطة (مقشرة ومقطعة مكعبات)","1 حبة بصل متوسطة (مقطعة مكعبات)","1 ملعقة كبيرة زيت زيتون"],
["في قدر كبير، سخّن زيت الزيتون على نار متوسطة إلى عالية. أضف البصل وقلّبه لمدة 4 دقائق. أضف الجزر والشمر وتبّلهما بالملح والفلفل الأسود. قلّبها لمدة 3 دقائق. أضف الثوم وقلّبه لمدة دقيقة واحدة.","أضف المرق والملفوف واللفت السويدي إلى القدر. اتركه حتى يغلي. خفّض الحرارة إلى منخفضة، وغطِّ القدر، واتركه يغلي بهدوء من 45 دقيقة إلى ساعة. أضف المعكرونة، وارفع الحرارة إلى متوسطة، واطهِ لمدة 7 دقائق، أو حتى تلين المعكرونة. اغرف الحساء في الأوعية وزيّن كل وعاء بالثوم المعمّر (الشيف)."]))

add(6058861,
es=T("Rábanos asados","Aunque los rábanos crudos son deliciosos, con su sabor picante y avivado, asarlos resalta un nivel de dulzor que equilibra el picante. Los rábanos asados son fáciles de preparar y, al ser una verdura de raíz sin almidón, son una excelente opción para personas con diabetes. ¡Pruebe servirlos con Lomo de cerdo con ajo y ajonjolí para una comida sabrosa!","3","1/2 taza",
["16 onzas de rábanos","2 dientes de ajo (picados)","1 cucharada de aceite de oliva","1/4 cucharadita de sal","1/2 jugo de 1/2 limón"],
["Precaliente el horno a 425 grados F.","Lave los rábanos y recorte los tallos. Reserve algunas hojas de los rábanos y córtelas en tiras finas para decorar. Parta los rábanos por la mitad y mézclelos con el ajo, el aceite y la sal.","Forre una bandeja para hornear con papel de aluminio y coloque los rábanos con el lado cortado hacia abajo. Colóquelos en el horno y áselos de 20 a 25 minutos, hasta que estén tiernos al pincharlos con un tenedor.","Retire del horno y mezcle con el jugo de limón y las hojas de rábano."]),
ar=T("فجل مشوي","على الرغم من أن الفجل النيئ لذيذ بنكهته الحارة المنعشة، فإن شيّه يُبرز درجة من الحلاوة توازن حدّته. الفجل المشوي سهل التحضير كخضار جذري خالٍ من النشا، مما يجعله خيارًا رائعًا لمرضى السكري. جرّب تقديمه مع فيليه لحم الخنزير بالثوم والسمسم للحصول على وجبة لذيذة!","3","½ كوب",
["16 أونصة فجل","2 فص ثوم (مفروم)","1 ملعقة كبيرة زيت زيتون","¼ ملعقة صغيرة ملح","½ عصير ½ ليمونة"],
["سخّن الفرن مسبقًا على 425 درجة فهرنهايت (220 درجة مئوية).","اغسل الفجل وقصّ السيقان. احتفظ ببضع أوراق من الفجل وقطّعها إلى شرائح رفيعة للتزيين. قسّم الفجل إلى نصفين وقلّبه مع الثوم والزيت والملح.","بطّن صينية خَبز بورق الألمنيوم وضع الفجل بحيث يكون الجانب المقطوع لأسفل. ضعه في الفرن واشوِه لمدة 20–25 دقيقة حتى يلين عند وخزه بالشوكة.","أخرجه من الفرن وقلّبه مع عصير الليمون وأوراق الفجل."]))

