add(6064318, ar=T("حساء القرع الجوزي السريع","استمتع بنكهات الخريف الغنية مع حساء القرع اللذيذ والسريع هذا. استخدام القرع الجوزي المجمد في هذه الوصفة يوفر الكثير من الوقت. تفقّد قسم الخضار في ممر الأطعمة المجمدة.","5","1 كوب",
["2 كيس (12 أونصة) قرع جوزي مجمد","1 ملعقة كبيرة زيت زيتون","1 حبة بصل متوسطة (مقطعة مكعبات)","1 حبة جزر كبيرة (مقطعة مكعبات)","2 فص ثوم (مفروم)","24 أونصة مرق دجاج قليل الصوديوم","½ ملعقة صغيرة فلفل أسود","⅛ ملعقة صغيرة مريمية مجففة (مجففة)"],
["سخّن القرع المجمد في الميكروويف لمدة 5 دقائق.","في قدر حساء كبير، سخّن الزيت على نار متوسطة إلى عالية. أضف البصل والجزر وقلّبهما لمدة 5 دقائق، أو حتى يصبحا شفافين. أضف الثوم وقلّبه لمدة 30 ثانية. أضف القرع وقلّبه لمدة 3 دقائق.","أضف بقية المكوّنات. اتركه حتى يغلي، ثم خفّض الحرارة واتركه يغلي بهدوء لمدة 15 دقيقة.","بعد أن يبرد الحساء قليلًا، انقله إلى الخلاط واخلطه حتى يصبح ناعمًا، أو استخدم خلاطًا يدويًا في القدر حتى يصبح ناعمًا. إن رغبت، أعد الحساء المهروس إلى القدر لإعادة تسخينه قبل التقديم."]))

add(6064401,
es=T("Ensalada Cobb de pollo con tocino de pavo","Esta ensalada Cobb de pollo está repleta de proteína magra, verduras frescas y grasas saludables para el corazón. Se prepara rápidamente, lo que la convierte en una excelente adición a su rotación de almuerzos.","4","3 onzas de pollo + 3 tazas de ensalada + 2 cucharadas de aderezo",
["12 onzas de pechuga de pollo sin hueso ni piel (en cubos)","1/4 cucharadita de pimentón","1/4 cucharadita de sal kosher (dividida)","1/8 cucharadita de pimienta negra","1 taza de yogur griego natural sin grasa","1 cucharadita de eneldo seco","1 cucharadita de cebollín seco","1 cucharadita de perejil seco","1 cucharadita de ajo en polvo","1 cucharadita de cebolla en polvo","1/2 cucharadita de granos de pimienta negra (triturados)","1 cucharada de vinagre de arroz","1-2 cucharadas de agua (según la consistencia deseada)","1 cabeza de lechuga romana (picada)","4 rebanadas de tocino de pavo (bajo en sodio, cocido y desmenuzado)","2 tomates roma (pera) grandes (en cubos)","1 aguacate mediano (en cubos)","1/2 taza de claras de huevo (cocidas)"],
["Caliente una sartén a fuego medio. Agregue la pechuga de pollo en cubos, el pimentón, ⅛ cucharadita de sal y la pimienta. Saltee hasta que el pollo esté completamente cocido a una temperatura interna de 165 grados F y dorado. Retire del fuego y reserve.","Para preparar el aderezo, combine el yogur griego, el eneldo, el cebollín, el perejil, el ajo en polvo, la cebolla en polvo, la pimienta negra, el vinagre de arroz, el agua y el ¼ de cucharadita de sal restante en una licuadora o procesador de alimentos y pulse hasta que quede suave.","Divida la lechuga en 4 tazones. Cubra con el pollo, el tocino, los tomates, el aguacate y las claras de huevo. Rocíe con el aderezo."]),
ar=T("سلطة كوب بالدجاج مع لحم الديك الرومي المقدد","هذه السلطة كوب بالدجاج مليئة بالبروتين قليل الدهن والخضار الطازجة والدهون الصحية للقلب. تُحضَّر بسرعة، مما يجعلها إضافة رائعة إلى وجبات الغداء المتنوعة لديك.","4","3 أونصات دجاج + 3 كوب سلطة + 2 ملعقة كبيرة صلصة",
["12 أونصة صدر دجاج بدون عظم وبدون جلد (مقطع مكعبات)","¼ ملعقة صغيرة بابريكا","¼ ملعقة صغيرة ملح كوشر (مقسّم)","⅛ ملعقة صغيرة فلفل أسود","1 كوب زبادي يوناني سادة خالٍ من الدسم","1 ملعقة صغيرة شبت مجفف","1 ملعقة صغيرة ثوم معمّر (شيف) مجفف","1 ملعقة صغيرة بقدونس مجفف","1 ملعقة صغيرة مسحوق الثوم","1 ملعقة صغيرة مسحوق البصل","½ ملعقة صغيرة حبوب فلفل أسود (مجروشة)","1 ملعقة كبيرة خل الأرز","1-2 ملعقة كبيرة ماء (حسب القوام المطلوب)","1 رأس خس روماني (مفروم)","4 شريحة لحم ديك رومي مقدد (قليل الصوديوم، مطبوخ ومفتت)","2 حبة طماطم رومي (برقوقية) كبيرة (مقطعة مكعبات)","1 حبة أفوكادو متوسطة (مقطعة مكعبات)","½ كوب بياض بيض (مسلوق)"],
["سخّن مقلاة على نار متوسطة. أضف صدر الدجاج المقطع مكعبات والبابريكا و⅛ ملعقة صغيرة ملح والفلفل. قلّبه حتى ينضج الدجاج تمامًا إلى درجة حرارة داخلية 165 درجة فهرنهايت (75 درجة مئوية) ويصبح ذهبي اللون. ارفعه عن النار وضعه جانبًا.","لتحضير الصلصة، ضع الزبادي اليوناني والشبت والثوم المعمّر (الشيف) والبقدونس ومسحوق الثوم ومسحوق البصل والفلفل الأسود وخل الأرز والماء و¼ ملعقة صغيرة المتبقية من الملح في خلاط أو محضّرة طعام وشغّلها بنبضات متقطعة حتى تصبح ناعمة.","وزّع الخس على 4 أوعية. ضع فوقه الدجاج واللحم المقدد والطماطم والأفوكادو وبياض البيض. رشّ الصلصة."]))

add(6065602, ar=T("سلايدر الدجاج بصلصة الباربكيو","تتطلب وصفة السلايدر هذه دجاجًا مفرومًا، ولكن الديك الرومي المفروم قليل الدهن يناسبها أيضًا. قدّم هذه السلايدر اللطيفة كمقبلات أو وجبة خفيفة في المرة القادمة التي تستضيف فيها حفل شواء!","6","1 سلايدر",
["16 أونصة دجاج مفروم","1 بيضة","½ كوب شوفان","¼ ملعقة صغيرة ملح (اختياري)","¼ ملعقة صغيرة فلفل أسود","½ ملعقة صغيرة بابريكا مدخنة","½ ملعقة صغيرة مسحوق الفلفل الحار (تشيلي)","¼ كوب صلصة باربكيو (خالية من السكر)","6 حبات خبز سلايدر بالقمح الكامل","6 أوراق خس بيب أو بوسطن","1 حبة طماطم متوسطة (مقطعة إلى 6 شرائح)"],
["سخّن شواية داخلية أو خارجية مسبقًا.","في وعاء متوسط، اخلط الدجاج المفروم والبيض والشوفان والبابريكا ومسحوق الفلفل الحار والفلفل. اخلط جيدًا.","قسّم خليط اللحم إلى 6 أجزاء متساوية واضغط عليها لتشكيل أقراص.","اشوِ السلايدر على جانب واحد لمدة 4-5 دقائق. اقلب السلايدر وافرد عليه 2 ملعقة كبيرة من صلصة الباربكيو. تابع الشيّ لمدة 4 – 5 دقائق واقلبه مرة أخرى. افرد عليه ما تبقى من صلصة الباربكيو. اشوِه لمدة 2-3 دقائق أخرى أو حتى تنضج البرغر تمامًا. يجب أن تصل درجة حرارتها الداخلية إلى 165° فهرنهايت (75° مئوية).","افتح خبز السلايدر. ضع قرصًا على النصف السفلي من كل واحدة. ضع فوق كل منها ورقة خس وشريحة طماطم."]))

add(6067326,
es=T("Bocaditos de claras de huevo con espinaca y mozzarella","¡Es fácil preparar sus propios bocaditos de huevo en casa! De esa manera, puede controlar exactamente lo que llevan. Estos bocaditos de claras de huevo con espinaca y mozzarella, bajos en carbohidratos, son un desayuno rápido para llevar que puede preparar con anticipación.","4","3 bocaditos de claras de huevo",
["1 cucharadita de aceite de oliva","2 cucharadas de cebolla morada","1 taza de espinaca (picada)","1 taza de claras de huevo (aproximadamente 8 claras de huevo grandes)","1 cucharadita de orégano seco","1/2 cucharadita de sal","1/2 cucharadita de pimienta negra","1 rocío, 0.25 g de aceite antiadherente en aerosol","1/4 taza de tomates roma (pera) (en cubos)","3 cucharadas de queso mozzarella (rallado)"],
["Precaliente el horno a 350 grados F.","En una sartén, caliente el aceite de oliva a fuego medio.","Agregue la cebolla morada en cubos y cocine hasta que se ablande.","Agregue la espinaca picada a la sartén y cocine hasta que se marchite.","En un tazón, bata las claras de huevo y sazone con el orégano, la sal y la pimienta.","Engrase un molde para muffins con aceite en aerosol.","Distribuya la espinaca y la cebolla salteadas de manera uniforme entre las cavidades del molde para muffins.","Vierta las claras de huevo batidas sobre la espinaca y la cebolla en cada cavidad. Espolvoree los tomates en cubos y el queso mozzarella por encima.","Hornee en el horno precalentado durante 15 minutos o hasta que las claras de huevo estén cuajadas.","Deje enfriar los bocaditos de claras de huevo unos minutos antes de retirarlos del molde para muffins."]),
ar=T("لقيمات بياض البيض بالسبانخ والموزاريلا","من السهل تحضير لقيمات البيض بنفسك في المنزل! بهذه الطريقة يمكنك مراقبة ما يدخل فيها بالضبط. تُعدّ لقيمات بياض البيض هذه بالسبانخ والموزاريلا قليلة الكربوهيدرات وجبة إفطار سريعة لتأخذها معك ويمكنك تحضيرها مسبقًا.","4","3 لقيمات بياض بيض",
["1 ملعقة صغيرة زيت زيتون","2 ملعقة كبيرة بصل أحمر","1 كوب سبانخ (مفرومة)","1 كوب بياض بيض (حوالي 8 بياض بيض كبير)","1 ملعقة صغيرة أوريجانو مجفف","½ ملعقة صغيرة ملح","½ ملعقة صغيرة فلفل أسود","1 بخّة، 0.25 غرام رذاذ طهي غير لاصق","¼ كوب طماطم رومي (برقوقية) (مقطعة مكعبات)","3 ملعقة كبيرة جبن موزاريلا (مبشور)"],
["سخّن الفرن مسبقًا على 350 درجة فهرنهايت (175 درجة مئوية).","في مقلاة، سخّن زيت الزيتون على نار متوسطة.","أضف البصل الأحمر المقطع مكعبات واطهِه حتى يلين.","أضف السبانخ المفرومة إلى المقلاة واطهِها حتى تذبل.","في وعاء، اخفق بياض البيض وتبّله بالأوريجانو والملح والفلفل.","افرك قالب المافن برذاذ الطهي.","وزّع السبانخ والبصل المقليين بالتساوي على تجاويف قالب المافن.","صبّ بياض البيض المخفوق فوق السبانخ والبصل في كل تجويف. انثر الطماطم المقطعة مكعبات وجبن الموزاريلا فوقها.","اخبزها في الفرن المسخّن مسبقًا لمدة 15 دقيقة أو حتى يتماسك بياض البيض.","اترك لقيمات بياض البيض تبرد بضع دقائق قبل إخراجها من قالب المافن."]))

add(6068003,
es=T("Salmón en salsa de tomates secos sobre fideos de calabacín","Acomodado en una salsa cremosa y vivificante, el salmón con hojas verdes tiernas sobre fideos de calabacín es un plato de cena bajo en carbohidratos. Los tomates secos le dan un sabor vibrante a esta salsa cremosa y ligera.\n\nNota: el análisis nutricional incluye el queso feta","4","1 filete de salmón de 4 onzas + 1/2 taza de salsa + 1 taza de calabacín",
["1 libra de filetes de salmón sockeye","1/2 cucharadita de sal kosher","1/2 cucharadita de pimienta negra","1/4 taza de cebolla","2 dientes de ajo (picados)","1/4 taza de tomates secos (en aceite, escurridos y picados)","1/2 taza de caldo de verduras","1/4 taza de media crema (half-and-half) sin grasa","1 cucharadita de maicena","4 tazas de hojas verdes variadas (o col rizada y espinaca tiernas)","4 tazas de fideos de calabacín","1 cucharadita de aceite de oliva","2 cucharadas de queso feta reducido en grasa (opcional)"],
["Caliente una sartén grande a fuego medio. Rocíe con un poco de aceite en aerosol. Sazone el salmón con sal y pimienta. Coloque el salmón con la piel hacia abajo en la sartén y cocine unos 3 minutos, hasta que la piel esté crujiente. Voltee el salmón y cocine otros 3 minutos, hasta que se despegue fácilmente de la sartén y la parte superior esté ligeramente dorada. Retire de la sartén y pase a un plato.","Agregue la cebolla, el ajo y los tomates a la sartén y saltee durante 3 minutos. Vierta lentamente el caldo de verduras y revuelva, raspando los trocitos dorados del fondo de la sartén.","Disuelva la maicena en la media crema (half-and-half) y mezcle con el caldo de verduras, cocinando uno o dos minutos hasta que la salsa comience a espesar. Incorpore las hojas verdes y cocine hasta que se marchiten. Regrese el salmón a la sartén y cocine a fuego lento, tapado, hasta que el salmón alcance una temperatura interna de 145 grados F.","Envuelva los fideos de calabacín en una toalla limpia y exprima suavemente para sacar la mayor cantidad de humedad posible. Caliente el aceite de oliva en una sartén grande antiadherente. Agregue los fideos de calabacín y saltee de 1 a 2 minutos, hasta que estén calientes.","Divida los fideos entre 4 platos. Coloque 1 filete de salmón en cada uno. Cubra con la salsa y espolvoree con queso feta."]),
ar=T("سلمون في صلصة الطماطم المجففة فوق معكرونة الكوسا","يُعدّ السلمون مع الخضار الورقية الصغيرة فوق معكرونة الكوسا، المحتضَن في صلصة كريمية منعشة، عشاءً شهيًا قليل الكربوهيدرات. تضفي الطماطم المجففة نكهة زاهية على هذه الصلصة الكريمية الخفيفة.\n\nملاحظة: يتضمن التحليل الغذائي جبن الفيتا","4","1 شريحة سلمون 4 أونصات + ½ كوب صلصة + 1 كوب كوسا",
["1 رطل شرائح سلمون سوكاي","½ ملعقة صغيرة ملح كوشر","½ ملعقة صغيرة فلفل أسود","¼ كوب بصل","2 فص ثوم (مفروم)","¼ كوب طماطم مجففة (معبأة بالزيت، مصفّاة، مفرومة)","½ كوب مرق خضار","¼ كوب نصف كريمة ونصف حليب خالٍ من الدسم (half-and-half)","1 ملعقة صغيرة نشا الذرة","4 كوب خضار ورقية مشكلة (أو كرنب صغير وسبانخ صغيرة)","4 كوب معكرونة كوسا","1 ملعقة صغيرة زيت زيتون","2 ملعقة كبيرة جبن فيتا قليل الدسم (اختياري)"],
["سخّن مقلاة كبيرة على نار متوسطة. رشّها بقليل من رذاذ الطهي. تبّل السلمون بالملح والفلفل. ضع السلمون بحيث يكون الجلد لأسفل في المقلاة واطهِه نحو 3 دقائق، حتى يصبح الجلد مقرمشًا. اقلب السلمون واطهِه 3 دقائق أخرى، حتى ينفصل بسهولة عن المقلاة ويصبح وجهه بنيًا خفيفًا. أخرجه من المقلاة وضعه على طبق.","أضف البصل والثوم والطماطم إلى المقلاة وقلّبها لمدة 3 دقائق. صبّ مرق الخضار ببطء وحرّك مع كشط أي قطع بنية من قاع المقلاة.","أذب النشا في نصف الكريمة ونصف الحليب (half-and-half) وأضفه إلى مرق الخضار، واطهِه دقيقة أو دقيقتين حتى تبدأ الصلصة بالتكاثف. أضف الخضار الورقية واطهِها حتى تذبل. أعد السلمون إلى المقلاة واتركه يغلي بهدوء مع التغطية حتى تصل درجة حرارته الداخلية إلى 145 درجة فهرنهايت (65 درجة مئوية).","لفّ معكرونة الكوسا في منشفة نظيفة واعصرها برفق لإخراج أكبر قدر ممكن من الرطوبة. سخّن زيت الزيتون في مقلاة كبيرة غير لاصقة. أضف معكرونة الكوسا وقلّبها لمدة 1–2 دقيقة، حتى تسخن.","وزّع المعكرونة على 4 أطباق. ضع شريحة سلمون واحدة على كل طبق. ضع فوقها الصلصة وانثر جبن الفيتا."]))
save(4)
